@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        // DispatcherServlet routed GET /api/orders/123 to this method
        var order = orderService.findById(id);
        return order.map(ResponseEntity::ok)
                    .orElse(ResponseEntity.notFound().build());
    }

    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody Order order) {
        // DispatcherServlet invoked HttpMessageConverter to deserialize JSON
        var saved = orderService.save(order);
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {

    @GetMapping  // HandlerMapping maps GET /api/products here
    public List<Product> listProducts() {
        return List.of(
            new Product(1L, "Laptop"),
            new Product(2L, "Mouse")
        );
    }

    @GetMapping("/{id}")  // HandlerMapping maps GET /api/products/42 here
    public Product getProduct(@PathVariable Long id) {
        return new Product(id, "Laptop");
    }

    @PostMapping(consumes = "application/json")  // Matches only if Content-Type is JSON
    public Product createProduct(@RequestBody Product product) {
        return product;
    }
}

