@Component
public class TimingInterceptor implements HandlerInterceptor {
    private static final Logger log = LoggerFactory.getLogger(TimingInterceptor.class);

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        long startTime = System.currentTimeMillis();
        request.setAttribute("startTime", startTime);  // Store for later use
        log.info("Request started: {} {}", request.getMethod(), request.getRequestURI());
        return true;  // Continue to controller — false would short-circuit
    }

    @Override
    public void postHandle(HttpServletRequest request, HttpServletResponse response, Object handler, ModelAndView modelAndView) {
        log.info("Controller method finished");
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
        long startTime = (Long) request.getAttribute("startTime");
        long duration = System.currentTimeMillis() - startTime;
        log.info("Request completed in {}ms", duration);
    }
}

@Configuration
class WebConfig implements WebMvcConfigurer {
    @Autowired
    private TimingInterceptor timingInterceptor;

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(timingInterceptor)
                .addPathPatterns("/api/**");  // Only intercept /api/* requests
    }
}

@Controller  // Note: @Controller, NOT @RestController
@RequestMapping("/web")
public class UserWebController {
    private final UserService userService;

    public UserWebController(UserService userService) {
        this.userService = userService;
    }

    @GetMapping("/users")
    public String listUsers(Model model) {
        var users = userService.findAll();
        model.addAttribute("users", users);  // Add data to model
        return "user-list";  // ViewResolver resolves to templates/user-list.html
    }

    @GetMapping("/users/{id}")
    public String userDetails(@PathVariable Long id, Model model) {
        var user = userService.findById(id);
        model.addAttribute("user", user);
        return "user-details";  // Resolved to templates/user-details.html
    }
}

@RestController  // Implicit @ResponseBody on all methods
@RequestMapping("/api/customers")
public class CustomerController {
    private final CustomerRepository customerRepository;

    public CustomerController(CustomerRepository customerRepository) {
        this.customerRepository = customerRepository;
    }

    @GetMapping("/{id}")
    public Customer getCustomer(@PathVariable Long id) {
        // MappingJackson2HttpMessageConverter serializes Customer to JSON
        return customerRepository.findById(id)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    }

    @PostMapping
    public Customer createCustomer(@RequestBody Customer customer) {
        // MappingJackson2HttpMessageConverter deserialized JSON to Customer
        return customerRepository.save(customer);
    }
}

record Customer(Long id, String name, String email) {}
